struct Feed { std::string name = "md"; };
auto g_feed = std::make_shared<Feed>();
void on_heartbeat() { g_feed.reset(); }
void poll(const std::weak_ptr<Feed>& w) {
  if (!w.expired()) {
    on_heartbeat();   // "another thread"
    auto f = w.lock();
    std::cout << f->name << '\n';
  }
}
int main() { poll(g_feed); }

void poll(const std::weak_ptr<Feed>& w) {
  if (auto f = w.lock()) {   // owner now
    on_heartbeat();          // cannot kill it
    std::cout << f->name << '\n';
  } else {
    std::cout << "feed gone\n";
  }
}
// poll twice: md, then feed gone

struct Button {
  const char* name = "ok";
  ~Button() { std::puts("~Button"); }
};
int main() {
  std::function<void()> cb;
  {
    auto btn = std::make_shared<Button>();
    cb = [&btn] { std::puts(btn->name); };
  }
  cb();
}

{
  auto btn = std::make_shared<Button>();
  cb = [w = std::weak_ptr(btn)] {
    if (auto b = w.lock()) std::puts(b->name);
    else std::puts("button gone");
  };
  cb();   // ok
}         // ~Button
cb();     // button gone

struct B;
struct A { std::shared_ptr<B> b;
  ~A() { std::cout << "~A "; } };
struct B { std::shared_ptr<A> a;
  ~B() { std::cout << "~B "; } };

int main() {
  auto a = std::make_shared<A>();
  auto b = std::make_shared<B>();
  a->b = b;  b->a = a;
  a.reset(); b.reset();
  std::cout << "end\n";
}

struct B {
  std::weak_ptr<A> a;  // does not own
  ~B() { std::cout << "~B "; }
};
// a.reset(): A hits 0, ~A runs,
// A's member b drops B to 1.
// b.reset(): B hits 0, ~B runs.

struct S : std::enable_shared_from_this<S> {};

int main() {
  S local;
  try {
    auto p = local.shared_from_this();
    std::cout << (p ? "owned" : "null");
  } catch (const std::exception& e) {
    std::cout << "threw " << e.what();
  }
}

class Session
  : public std::enable_shared_from_this<Session> {
  Session() = default;  // no stack objects
public:
  static std::shared_ptr<Session> create() {
    std::shared_ptr<Session> s(new Session);
    s->start();  // now shared_from_this works
    return s;
  }
  void start();
};
